"""Build a public catalogue without publishing paid files or legacy demo APIs."""
import json, re, shutil
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public'
source=(ROOT/'docs/framework/10_Pillars_Framework.md').read_text()
items=[]
for n,title,body in re.findall(r'### Pillar (\d+): ([^\n]+)\n(.*?)(?=\n### |\n---)',source,re.S):
 points=[s[2:] for s in body.splitlines() if s.startswith('- ')]
 slug=re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')
 items.append(dict(number=int(n),title=title,slug=slug,points=points,checkout_enabled=False))
assert len(items)==10
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir()
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#101411;color:#f4f1e7;font:18px/1.65 system-ui,sans-serif}a{color:inherit}header,main,footer{max-width:1200px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;border-bottom:1px solid #475044}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}h1{font:600 clamp(44px,7vw,88px)/1.05 Georgia,serif;max-width:900px;margin:24px 0}h2{font:500 36px/1.2 Georgia,serif}h3{font-size:24px;line-height:1.25}.eyebrow,.num{color:#e8c978;letter-spacing:.12em;font-size:16px}.intro{font-size:23px;max-width:760px;color:#d5dccf}.hero{padding:60px 0}.button{display:inline-block;border:1px solid #e8c978;background:#e8c978;color:#172218;padding:14px 24px;border-radius:4px;text-decoration:none;font-weight:650;margin:12px 12px 12px 0}.secondary{background:transparent;color:#f4f1e7}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:20px}.card{border:1px solid #475044;padding:28px;background:#19221b;border-radius:6px}.card p{color:#d5dccf}.status{font-size:16px;color:#e8c978}.band{border-top:1px solid #475044;padding:48px 0;margin-top:48px}.note{color:#c8d2c3;max-width:780px}footer{border-top:1px solid #475044;font-size:16px}.steps{display:flex;gap:24px;flex-wrap:wrap}.steps p{flex:1;min-width:220px}a:focus-visible{outline:3px solid #fff;outline-offset:6px}@media(max-width:600px){header,main,footer{padding:22px}.hero{padding:36px 0}.intro{font-size:20px}}'''
def page(title,body,path):
 target=OUT/path;target.parent.mkdir(parents=True,exist_ok=True)
 target.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Major AI Mindset</title><meta name="description" content="Explore the ten pillars of Major AI Mindset. Practical learning for Caribbean communities, creators and builders everywhere."><link rel="stylesheet" href="/style.css"></head><body><header><a href="/" aria-label="Ten Pillars home"><strong>MAIM / THE TEN PILLARS</strong></a><nav aria-label="Main"><a href="/#pillars">Explore the pillars</a><a href="/series/">The series</a><a href="https://www.majoraimindset.com">Main MAIM site ↗</a></nav></header><main>{body}</main><footer>Major Dream Williams · Major AI Mindset<br>Timeless wisdom. Emerging technology. An evolving mindset.<br><a href="https://www.majoraimindset.com">Return to MAIM</a> · <a href="mailto:contact@majoraimindset.com">Contact</a></footer></body></html>''')
(OUT/'style.css').write_text(style)
cards=''.join(f'<article class="card"><span class="num">PILLAR {p["number"]:02}</span><h3>{escape(p["title"])}</h3><p>{escape(p["points"][0])}</p><a href="/pillars/{p["slug"]}/">Explore this pillar →</a></article>' for p in items)
page('The Ten Pillars',f'''<section class="hero"><div class="eyebrow">THE MAJOR AI MINDSET COLLECTION</div><h1>Build a future<br>you can own.</h1><p class="intro">Ten connected pillars for turning knowledge into capability, culture into connection, and intention into lasting impact.</p><p class="note">Rooted in the Caribbean diaspora. Open to creators, families and communities everywhere.</p><a class="button" href="#pillars">Find your starting point</a><a class="button secondary" href="/series/">Explore the whole series</a></section><section id="pillars"><div class="eyebrow">ONE FRAMEWORK. MANY WAYS TO BEGIN.</div><h2>Choose the pillar that speaks to you.</h2><div class="grid">{cards}</div></section><section class="band"><h2>Read. Reflect. Make a Major Move.</h2><div class="steps"><p><strong>01 / Read</strong><br>Explore a principle that matters in your life today.</p><p><strong>02 / Reflect</strong><br>Connect it to your own situation, family and community.</p><p><strong>03 / Act</strong><br>Take one useful step. Observe what changes.</p></div></section><section class="band"><h2>Learn one pillar.<br>Connect the whole picture.</h2><p class="note">Individual e-book editions and a complete-series option are being prepared. Browse the learning framework now; purchasing will open when each edition and its delivery are ready.</p><a class="button" href="/series/">View collection details</a></section>''',Path('index.html'))
for p in items:
 bullets=''.join('<li>'+escape(s)+'</li>' for s in p['points'])
 page(p['title'],f'''<section class="hero"><div class="eyebrow">PILLAR {p['number']:02} / THE TEN PILLARS</div><h1>{escape(p['title'])}</h1><p class="intro">{escape(p['points'][0])}</p></section><div class="grid"><section class="card"><h2>Explore the ideas</h2><ul>{bullets}</ul><h3>Your reflection</h3><p>Where could this pillar make a difference in your life or community? Write down one small step you can take.</p></section><aside class="card"><div class="eyebrow">INDIVIDUAL E-BOOK</div><h2>Start with this pillar.</h2><p class="status">Edition in preparation · Purchasing not yet available</p><p>The individual edition, price and secure delivery are being finalized.</p><a class="button secondary" href="/series/">Compare with the full series</a></aside></div><section class="band"><a href="/#pillars">← Explore all ten pillars</a></section>''',Path('pillars')/p['slug']/'index.html')
page('The Complete Series','''<section class="hero"><div class="eyebrow">THE MAIM TEN PILLARS SERIES</div><h1>A connected framework.<br>A journey of your own.</h1><p class="intro">Explore identity, resilience, learning, ownership, community and legacy through all ten pillars.</p></section><section class="card"><h2>The complete-series option</h2><p>Choose the whole collection or begin with the pillar most relevant to you.</p><p class="status">Collection in preparation · Purchasing not yet available</p><p>Final contents, editions and pricing will be shown here before checkout opens.</p><a class="button" href="/#pillars">Browse the ten pillars</a></section><section class="band"><h2>Continue your MAIM journey</h2><p class="note">Begin with Awareness, Belief and Context, then explore the principles that help you apply technology with purpose.</p><a class="button secondary" href="https://www.majoraimindset.com">Explore Major AI Mindset ↗</a></section>''',Path('series/index.html'))
(OUT/'catalog.json').write_text(json.dumps(dict(pillars=items,series=dict(checkout_enabled=False)),indent=2))
(OUT/'health.json').write_text(json.dumps(dict(status='ok',service='maim-pillars-catalog',checkout='disabled')))
print(json.dumps(dict(event='catalog_build',pillars=len(items),pages=12,paid_assets_published=False)))
